import React, { useEffect, useState } from "react";

export default function Login() {
  const [scriptLoaded, setScriptLoaded] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // If script already present, mark loaded
    if (window.google) {
      setScriptLoaded(true);
      return;
    }

    // Create script and append
    const id = "google-identity-script";
    if (document.getElementById(id)) {
      // If script element exists but window.google not ready yet,
      // wait for a short interval to check again.
      const t = setInterval(() => {
        if (window.google) {
          setScriptLoaded(true);
          clearInterval(t);
        }
      }, 200);
      return () => clearInterval(t);
    }

    const script = document.createElement("script");
    script.src = "https://accounts.google.com/gsi/client";
    script.id = id;
    script.async = true;
    script.defer = true;
    script.onload = () => {
      setScriptLoaded(true);
      console.log("Google Identity script loaded");
    };
    script.onerror = () => {
      console.error("Failed to load Google Identity script");
    };
    document.head.appendChild(script);

    // don't remove the script on unmount; keep it for the app
  }, []);

  const handleGoogleResponse = (response) => {
    if (!response || !response.credential) {
      console.error("No credential in Google response", response);
      alert("Google sign-in failed: no credential received.");
      return;
    }

    try {
      const payload = JSON.parse(atob(response.credential.split(".")[1]));
      console.log("Google payload:", payload);
      alert(`Signed in as ${payload.email}`);
    } catch (err) {
      console.error("Failed to decode Google credential", err);
      alert("Failed to decode Google credential.");
    }
  };

  const handleGoogleSignIn = () => {
    // Guard: use window.google not global google (avoids ReferenceError)
    if (!window || !window.google) {
      alert("Google script not loaded yet. Please wait a moment and try again.");
      return;
    }

    setLoading(true);
    try {
      window.google.accounts.id.initialize({
        client_id: "284794061832-3cp9tbidnnp24obbtma1u17koe8oja5t.apps.googleusercontent.com",
        callback: handleGoogleResponse,
      });

      // Use prompt to open account chooser / popup
      window.google.accounts.id.prompt((notification) => {
        // optional callback for UX
        console.log("google prompt notification", notification);
        setLoading(false);
      });
    } catch (err) {
      console.error("Error calling google.accounts.id:", err);
      alert("Google sign-in error: " + (err?.message || err));
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="bg-white w-full max-w-sm p-6 rounded-xl shadow-md">
        <h2 className="text-2xl font-semibold text-center mb-6">Login</h2>

        {/* Username + Password Form */}
        <form className="space-y-4">
          <input
            type="text"
            placeholder="Username"
            className="w-full border rounded-lg p-3 focus:outline-none focus:border-blue-500"
          />

          <input
            type="password"
            placeholder="Password"
            className="w-full border rounded-lg p-3 focus:outline-none focus:border-blue-500"
          />

          <button
            type="submit"
            className="w-full bg-blue-600 text-white py-3 rounded-lg hover:bg-blue-700"
          >
            Login
          </button>
        </form>

        <h3 className="text-center mt-6 mb-2 font-semibold">Or</h3>

        <button
          onClick={handleGoogleSignIn}
          disabled={!scriptLoaded || loading}
          className={`w-full mt-4 flex items-center justify-center gap-2 border py-2 rounded-lg hover:bg-gray-50 ${(!scriptLoaded || loading) ? 'opacity-60 cursor-not-allowed' : ''}`}
        >
          <img
            src="https://www.svgrepo.com/show/475656/google-color.svg"
            alt="Google"
            className="w-5 h-5"
          />
          {loading ? 'Loading...' : (scriptLoaded ? 'Sign in with Google' : 'Loading Google...')}
        </button>

        <p className="mt-4 text-xs text-gray-500">If this button keeps showing "Loading Google...", add this script to your <code>public/index.html</code> &lt;head&gt;: <br/> <code>&lt;script src="https://accounts.google.com/gsi/client" async defer&gt;&lt;/script&gt;</code></p>
      </div>
    </div>
  );
}
